import { ElectronAPI } from '@electron-toolkit/preload'

// ---------------------------------------------------------------------------
// Shared types
// ---------------------------------------------------------------------------

/** A game entry safe to render — contains no raw file-system paths. */
export type GameEntry = {
  id: string
  name: string
  /** Base64 data URL — user-set cover image, SteamGridDB grid, or extracted exe icon. */
  cover?: string
  /** Base64 data URL — wide landscape art for the backdrop (SteamGridDB hero). */
  hero?: string
  /** CSS colour string used as the per-game accent, e.g. "#2f6bff". */
  color?: string
}

/** Returned by launchGame() and other operations that can fail. */
export type LaunchResult = {
  ok: boolean
  /** Plain-language error to show directly to the user when ok is false. */
  error?: string
}

/**
 * Returned by getStatus().
 * ok is false only when games.json exists but cannot be parsed at all.
 */
export type LibraryStatus = {
  ok: boolean
  games: GameEntry[]
  error?: string
  warnings: string[]
}

/** A game detected by scanStores() or scanFolder() — not yet in games.json. */
export type ScanCandidate = {
  name: string
  exe?: string
  uri?: string
  source: 'steam' | 'epic' | 'gog' | 'folder'
}

/** Returned by addGame() and editGame(). */
export type WriteResult = {
  ok: boolean
  error?: string
  game?: GameEntry
}

/** Input for addGame(). id is generated by main — do not send one. */
export type AddGameInput = {
  name: string
  exe?: string
  uri?: string
  cover?: string
  color?: string
  args?: string[]
}

/** Input for editGame(). Only include fields you want to change. */
export type EditGameInput = {
  name?: string
  exe?: string
  uri?: string
  cover?: string
  color?: string
  args?: string[]
}

/** App settings stored in settings.json. */
export type Settings = {
  /** SteamGridDB API key (free at steamgriddb.com). Required for cover art fetching. */
  steamGridDbApiKey?: string
  /** Whether to minimise the launcher window when a game launches. Default: true. */
  minimizeOnLaunch?: boolean
}

/** Play time record for one game. */
export type PlayRecord = {
  id: string
  /** ISO 8601 timestamp of the most recent launch. */
  lastPlayed: string
  /** Total accumulated play time in milliseconds. */
  totalMs: number
  /** Set while a session is in progress; cleared on window focus. */
  sessionStart?: string
}

/** Map of game id → PlayRecord, returned by getAllPlaytime(). */
export type PlaytimeMap = Record<string, PlayRecord>

// ---------------------------------------------------------------------------
// Window API
// ---------------------------------------------------------------------------

declare global {
  interface Window {
    electron: ElectronAPI
    api: {
      // ── Read ────────────────────────────────────────────────────────────
      /** Returns all valid games. cover/hero are data URLs; never raw paths. */
      listGames(): Promise<GameEntry[]>
      /** Full library load result — use to show parse errors and warnings. */
      getStatus(): Promise<LibraryStatus>

      // ── Launch + reveal ──────────────────────────────────────────────────
      /** Launch by id. Paths come from games.json in main — never from the UI. */
      launchGame(id: string): Promise<LaunchResult>
      /** Open the folder containing games.json in Explorer. */
      openGamesFile(): Promise<void>
      /** Open the folder containing a game's exe in Explorer. */
      revealGame(id: string): Promise<LaunchResult>

      // ── File / folder pickers ────────────────────────────────────────────
      /** Native file dialog for .exe files. Returns absolute path or null. */
      pickExe(): Promise<string | null>
      /** Native file dialog for image files. Returns absolute path or null. */
      pickCover(): Promise<string | null>
      /** Native folder dialog. Returns absolute path or null. Pass to scanFolder(). */
      pickFolder(): Promise<string | null>

      // ── CRUD ────────────────────────────────────────────────────────────
      /** Add a game. Main generates the id. exe/cover must be absolute paths. */
      addGame(input: AddGameInput): Promise<WriteResult>
      /** Patch an existing game. Only changed fields needed. */
      editGame(id: string, patch: EditGameInput): Promise<WriteResult>
      /** Remove a game by id. */
      removeGame(id: string): Promise<LaunchResult>

      // ── Scanning ────────────────────────────────────────────────────────
      /** Scan Steam, Epic, GOG. Returns candidates — nothing written until addGame(). */
      scanStores(): Promise<ScanCandidate[]>
      /** Scan a folder for .exe files. folderPath must come from pickFolder(). */
      scanFolder(folderPath: string): Promise<ScanCandidate[]>

      // ── Settings ────────────────────────────────────────────────────────
      /** Read the current app settings. */
      getSettings(): Promise<Settings>
      /**
       * Update settings. Only known fields are accepted; others are ignored.
       * Partial — omitted fields keep their existing values.
       */
      setSettings(patch: Partial<Settings>): Promise<LaunchResult>

      // ── Cover art ───────────────────────────────────────────────────────
      /**
       * Fetch cover + hero art from SteamGridDB for one game and cache to disk.
       * Returns the updated GameEntry on success. Requires steamGridDbApiKey in settings.
       */
      fetchArt(id: string): Promise<WriteResult>
      /**
       * Queue art fetches for every game that has no cached art.
       * Runs in the background — returns immediately.
       * Reload the library after a short delay or on next focus.
       */
      fetchArtAll(): Promise<{ ok: boolean; queued: number }>

      // ── Play time ───────────────────────────────────────────────────────
      /** Get the play time record for one game, or null if never played. */
      getPlaytime(id: string): Promise<PlayRecord | null>
      /** Get play time records for all games. */
      getAllPlaytime(): Promise<PlaytimeMap>
    }
  }
}
